from fastapi.responses import HTMLResponse
from . import fast_scalper_beta_001_legacy as legacy

HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta http-equiv="Cache-Control" content="no-store"><title>Fast Scalper Beta</title><style>
*{box-sizing:border-box}html,body{margin:0;background:#07101e;color:#eef3ff;font-family:Arial,Helvetica,sans-serif;overflow-x:hidden}body{min-width:320px}.wrap{max-width:760px;margin:auto;padding:12px 14px 28px}.head{margin:0 0 12px}.brand{display:flex;gap:8px;align-items:flex-start}.bolt{font-size:37px;line-height:.9}.brand h1{margin:0;font-size:28px;line-height:1.05}.sub{margin-top:5px;color:#9aa6bd;font-size:14px;white-space:nowrap;overflow:hidden}.topbar{position:absolute;right:14px;top:14px}.online{background:#062d25;color:#00d47a;border-radius:8px;padding:5px 7px;font-size:10px;font-weight:800}.gear{margin-left:7px;color:#9eabc4;font-size:20px}.card{background:#101b2f;border:1px solid #29405f;border-radius:19px;padding:13px;margin-bottom:11px;overflow:hidden}.stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{background:#091326;border-radius:13px;padding:10px 11px;min-width:0}.k{font-size:13px;color:#dbe3f3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.v{font-size:20px;font-weight:800;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.unit{font-size:11px;color:#95a3bc;font-weight:400}.modes{display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px;margin-top:9px}.btn{height:42px;border:0;border-radius:11px;color:#fff;background:#1763a9;font-size:11px;font-weight:800;padding:0 8px;cursor:pointer;min-width:0}.paper{background:#293b5a}.green{background:#00a85b}.red{background:#cb3049}.gray{background:#293a58}.note,.summary,.hint{color:#99a5bd;font-size:11px;margin-top:7px}.control1{display:grid;grid-template-columns:1.05fr 1fr .72fr;gap:7px}.input{height:42px;width:100%;background:#091326;border:1px solid #304767;border-radius:11px;color:#eef3ff;padding:0 10px;font-size:15px;outline:none;min-width:0}.profit{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;margin-top:8px}.check{display:flex;align-items:center;gap:5px;font-size:13px;white-space:nowrap}.check input{width:19px;height:19px;accent-color:#1682ee}.actions{display:grid;grid-template-columns:1.45fr 1.15fr .8fr;gap:7px;margin-top:8px}.off{display:flex;align-items:center;gap:8px;margin-top:7px}.off .btn{width:85px;height:36px}.session{font-size:11px;color:#9aa6bd;white-space:nowrap}.status{min-height:15px;color:#9aa6bd;font-size:11px;margin-top:4px}.sectionHead,.slotHead,.collapseHead{display:flex;justify-content:space-between;align-items:center;gap:8px}.title{font-size:20px;font-weight:800;line-height:1.05}.badge{background:#c52f47;border-radius:8px;padding:4px 6px;font-size:8px;font-weight:800;white-space:nowrap}.empty{color:#8e9ab1;font-size:12px;margin-top:7px}.tradeitem{font-size:11px;color:#cbd5e7;padding:7px 2px;border-bottom:1px solid #2b405d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.collapseHead{cursor:pointer}.collapseBtn{height:32px;border:1px solid #304767;border-radius:8px;background:#091326;color:#eef3ff;padding:0 9px;font-size:10px;font-weight:800}.pool{margin-top:9px;max-height:440px;overflow:auto}.rowline{display:grid;grid-template-columns:23px minmax(65px,1fr) 48px 48px 43px 67px;gap:5px;align-items:center;padding:6px 2px;border-bottom:1px solid #263a57;font-size:10px}.pair{font-weight:800}.muted{color:#94a1b8}.addbtn{height:27px;border:0;border-radius:7px;background:#245b91;color:#fff;font-size:8px;font-weight:800;padding:0 5px}.auto{font-size:10px;color:#a4afc2;font-weight:800;display:flex;align-items:center;gap:5px}.auto input{width:18px;height:18px;accent-color:#1682ee}.slots{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:9px}.slotbox{display:grid;grid-template-columns:23px 1fr;gap:5px;align-items:center}.slotnum{font-size:9px;color:#75839c;text-align:center}.slot{height:39px;background:#091326;border:1px solid #304767;border-radius:10px;color:#edf3ff;padding:0 8px;font-size:12px;width:100%;min-width:0;outline:none}.slot:disabled{opacity:.85}.slotActions{display:flex;gap:7px;margin-top:8px}.slotActions .btn{height:36px}.slotActions .btn:first-child{flex:1}@media(max-width:520px){.online{display:none}.brand h1{font-size:27px}.sub{font-size:13px}.card{padding:12px}.metric{padding:9px}.k{font-size:12px}.v{font-size:18px}.rowline{grid-template-columns:22px minmax(60px,1fr) 46px 45px 41px 64px;font-size:9px}.addbtn{font-size:7px}}
</style></head><body><div class="topbar"><span class="online">● ONLINE</span><span class="gear">⚙</span></div><main class="wrap"><header class="head"><div class="brand"><span class="bolt">⚡</span><div><h1>Fast Scalper Beta</h1><div class="sub">Version 0.01 REPAIR PAPER · Trading TF: 3m</div></div></div></header>
<section class="card"><div class="stats"><div class="metric"><div class="k">Account Balance</div><div class="v"><span id="account">1850.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Bot Balance</div><div class="v"><span id="bot">150.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Reserve</div><div class="v"><span id="reserve">1700.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Session PnL</div><div class="v"><span id="pnl">0.0000</span> <span class="unit">USDT</span></div></div></div><div class="modes"><button class="btn paper" onclick="setMode('PAPER')">PAPER</button><button class="btn" onclick="setMode('BINANCE_TEST')">BINANCE TEST</button><button class="btn" onclick="testBinance()">TEST BINANCE</button></div><div class="note" id="note">AUTO TOP-10 active</div></section>
<section class="card"><div class="control1"><input id="allocation" class="input" inputmode="decimal" value="150"><button class="btn" onclick="setAllocation()">SET BOT BALANCE</button><button class="btn red" onclick="withdraw()">WITHDRAW</button></div><div class="profit"><input id="profit" class="input" inputmode="decimal" value="0.33"><label class="check"><input id="reinvest" type="checkbox" checked> Reinvest</label></div><div class="actions"><button class="btn green" onclick="startBot()">BOT ON · ACTIVE</button><button class="btn red" onclick="emergency()">EMERGENCY</button><button class="btn gray" onclick="resetBot()">RESET</button></div><div class="off"><button class="btn red" onclick="stopBot()">BOT OFF</button><div class="session" id="session">SESSION 00:00 · 24H 00:00</div></div><div class="status" id="status"></div></section>
<section class="card"><div class="sectionHead"><div class="title">Open Positions</div><div id="badge" class="badge">BOT OFF · TRADING STOPPED</div></div><div id="positions"><div class="empty">No open positions</div></div></section>
<section class="card"><div class="sectionHead"><div class="title">Closed Trades</div><div id="closedCount" class="summary">0</div></div><div id="closedSummary" class="summary">No closed trades</div></section>
<section class="card"><div class="title">Last Ten</div><div id="lastTen"><div class="empty">No closed trades</div></div></section>
<section class="card"><div class="collapseHead" onclick="togglePool()"><div class="title">Rotation Pool · TOP-20</div><button class="collapseBtn" id="poolBtn">EXPAND</button></div><div id="poolBody" style="display:none"><div class="pool" id="pool"><div class="empty">Waiting for radar data…</div></div></div></section>
<section class="card"><div class="slotHead"><div class="title">Slots · TOP-10</div><label class="auto">AUTO TOP-10 <input id="autoTop" type="checkbox" checked onchange="toggleAuto()"></label></div><div class="slots" id="slots"></div><div class="slotActions"><button class="btn" onclick="addTop10()">ADD TOP 10</button><button class="btn gray" onclick="clearSlots()">CLEAR</button></div><div class="hint">AUTO TOP-10 selects the current ten leaders. Turn it off to edit slots or add a pair from Rotation Pool.</div></section></main>
<script>
const $=id=>document.getElementById(id),num=x=>Number(x||0).toFixed(4),age=s=>{s=Math.max(0,Math.floor(Number(s||0)));return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},api=async(p,o={})=>{const r=await fetch(p,{cache:'no-store',headers:{'Content-Type':'application/json'},...o});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||d.error||('HTTP '+r.status));return d},msg=t=>{$('status').textContent=t||''};let ranking=[];let poolOpen=false;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function refresh(){try{const s=await api('/api/state');$('account').textContent=num(s.account);$('bot').textContent=num(s.bot_balance);$('reserve').textContent=num(s.reserve);$('pnl').textContent=num(s.session_realized);$('profit').value=Number(s.profit_pct??.33).toFixed(2);$('reinvest').checked=!!s.reinvest;$('autoTop').checked=!!s.auto_top;$('note').textContent=s.auto_top?'AUTO TOP-10 active':'MANUAL TOP-10 active';$('session').textContent='SESSION '+age(s.session_age)+' · 24H '+age(s.day_age);$('badge').textContent=s.running?'BOT ON · ACTIVE':'BOT OFF · TRADING STOPPED';ranking=s.ranking||[];renderPositions(s.positions||[]);renderClosed(s.closed||[]);renderLastTen(s.closed||[]);renderPool();renderSlots(s.slots||[]);if(s.error)msg(s.error)}catch(e){msg(e.message)}}
function renderPositions(a){$('positions').innerHTML=a.length?a.map(p=>'<div class="tradeitem"><b>'+esc(p.symbol)+'</b> · '+num(p.stake)+' USDT · PnL '+num(p.delta_usdt)+' USDT · '+age(p.age_seconds)+'</div>').join(''):'<div class="empty">No open positions</div>'}
function renderClosed(a){$('closedCount').textContent=String(a.length);$('closedSummary').textContent=a.length?'Closed: '+a.length+' · PnL: '+num(a.reduce((v,x)=>v+Number(x.pnl||0),0))+' USDT':'No closed trades'}
function renderLastTen(a){$('lastTen').innerHTML=a.length?a.slice(0,10).map((p,i)=>'<div class="tradeitem"><b>'+String(i+1).padStart(2,'0')+' · '+esc(p.symbol)+'</b> · '+num(p.stake)+' USDT · PnL '+num(p.pnl)+' USDT · '+esc(p.reason||'CLOSED')+'</div>').join(''):'<div class="empty">No closed trades</div>'}
function renderPool(){if(!poolOpen)return;let h='<div class="rowline muted"><span>#</span><span>PAIR</span><span>SIGNAL</span><span>24H</span><span>SCORE</span><span>ACTION</span></div>';ranking.slice(0,20).forEach((x,i)=>h+='<div class="rowline"><span>'+String(i+1).padStart(2,'0')+'</span><span class="pair">'+esc(x.symbol)+'</span><span>'+esc(x.signal||'WAIT')+'</span><span>'+Number(x.change_24h_pct??x.change??0).toFixed(2)+'%</span><span>'+Number(x.entry_score??x.score??0).toFixed(1)+'</span><button class="addbtn" onclick="addToSlot(\''+esc(x.symbol)+'\')">ADD TO SLOT</button></div>');$('pool').innerHTML=ranking.length?h:'<div class="empty">Waiting for radar data…</div>'}
function togglePool(){poolOpen=!poolOpen;$('poolBody').style.display=poolOpen?'block':'none';$('poolBtn').textContent=poolOpen?'COLLAPSE':'EXPAND';if(poolOpen)renderPool()}
function renderSlots(a){const selected=$('autoTop').checked?ranking.slice(0,10).map(x=>x.symbol):a.slice(0,10);const el=$('slots');el.innerHTML='';for(let i=0;i<10;i++){const box=document.createElement('div');box.className='slotbox';const n=document.createElement('span');n.className='slotnum';n.textContent=String(i+1).padStart(2,'0');const x=document.createElement('input');x.className='slot';x.placeholder='USDT pair';x.value=selected[i]||'';x.disabled=$('autoTop').checked;box.append(n,x);el.appendChild(box)}}
async function toggleAuto(){try{const en=$('autoTop').checked;await api('/api/auto-top',{method:'POST',body:JSON.stringify({enabled:en})});msg(en?'AUTO TOP-10 enabled':'Manual TOP-10 enabled');await refresh()}catch(e){msg(e.message)}}
async function persist(a,auto=false){await api('/api/slots',{method:'POST',body:JSON.stringify({slots:a,profit_pct:Number($('profit').value.replace(',','.'))||.33,reinvest:$('reinvest').checked,auto_top:auto})});await refresh()}
async function addTop10(){try{const a=ranking.slice(0,10).map(x=>x.symbol);if(a.length<10)throw Error('Radar has fewer than 10 pairs');$('autoTop').checked=false;await persist(a,false);msg('TOP-10 added to slots')}catch(e){msg(e.message)}}
async function addToSlot(s){try{const inputs=[...document.querySelectorAll('.slot')];$('autoTop').checked=false;let i=inputs.findIndex(x=>!x.value.trim());if(i<0)i=0;inputs[i].value=s.replace('/','').toUpperCase();await persist(inputs.map(x=>x.value.trim().toUpperCase()).filter(Boolean),false);msg(s+' added to slot '+(i+1))}catch(e){msg(e.message)}}
async function clearSlots(){try{$('autoTop').checked=false;await persist([],false);msg('Slots cleared')}catch(e){msg(e.message)}}
document.addEventListener('change',e=>{if(e.target.classList&&e.target.classList.contains('slot')&&!$('autoTop').checked){const a=[...document.querySelectorAll('.slot')].map(x=>x.value.trim().toUpperCase()).filter(Boolean);persist(a,false).catch(x=>msg(x.message))}});
async function setMode(m){try{await api('/api/mode',{method:'POST',body:JSON.stringify({mode:m})});msg('Mode set');await refresh()}catch(e){msg(e.message)}}async function testBinance(){try{const d=await api('/api/test-binance',{method:'POST'});msg(d.message||'Binance Testnet connection OK')}catch(e){msg(e.message)}}async function setAllocation(){try{await api('/api/allocation',{method:'POST',body:JSON.stringify({amount:Number($('allocation').value.replace(',','.'))})});msg('Bot balance set');await refresh()}catch(e){msg(e.message)}}async function withdraw(){try{const a=prompt('Withdraw amount, USDT','0.00');if(a===null)return;await api('/api/withdraw',{method:'POST',body:JSON.stringify({amount:Number(a.replace(',','.'))})});msg('Withdraw completed');await refresh()}catch(e){msg(e.message)}}async function startBot(){try{await api('/api/paper/start',{method:'POST',body:JSON.stringify({profit_pct:Number($('profit').value.replace(',','.'))||.33,reinvest:$('reinvest').checked})});msg('Bot active');await refresh()}catch(e){msg(e.message)}}async function stopBot(){try{await api('/api/paper/stop',{method:'POST'});msg('Bot OFF — new entries stopped');await refresh()}catch(e){msg(e.message)}}async function emergency(){try{await api('/api/paper/emergency',{method:'POST'});msg('Emergency stop completed');await refresh()}catch(e){msg(e.message)}}async function resetBot(){try{await api('/api/reset',{method:'POST'});msg('Reset completed');await refresh()}catch(e){msg(e.message)}}refresh();setInterval(refresh,1000);
</script></body></html>'''

for r in list(legacy.app.router.routes):
    if getattr(r,'path',None)=='/' and 'GET' in (getattr(r,'methods',set()) or set()): legacy.app.router.routes.remove(r)
@legacy.app.get('/',response_class=HTMLResponse)
async def approved_home():
    response=HTMLResponse(HTML); response.headers['Cache-Control']='no-store, no-cache, must-revalidate, max-age=0'; response.headers['Pragma']='no-cache'; response.headers['Expires']='0'; return response

print('FAST_SCALPER_APPROVED_UI_ORDER=OPEN,CLOSED,LAST10,POOL_COLLAPSIBLE,SLOTS_TOP10_MANUAL_ADD=1',flush=True)
